 "content": "def transform(grid):
    """Connect same-colored marker cells along shared rows/columns of a grid of rooms."""
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    rooms = []
    markers = {2: [], 3: []}
    for ri in range(len(rb) - 1):
        r0, r1 = rb[ri] + 1, rb[ri + 1]
        for ci in range(len(cb) - 1):
            c0, c1 = cb[ci] + 1, cb[ci + 1]
            rooms.append((ri, ci, r0, r1, c0, c1))
            colors = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, 8)}
            for color in colors:
                if color in markers:
                    markers[color].append((ri, ci))
    paint = {}
    for color, points in markers.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2 or c1 == c2:
                    for rr in range(min(r1, r2), max(r1, r2) + 1):
                        for cc in range(min(c1, c2), max(c1, c2) + 1):
                            paint.setdefault((rr, cc), set()).add(color)
    out = [row[:] for row in grid]
    for ri, ci, r0, r1, c0, c1 in rooms:
        colors = paint.get((ri, ci))
        if colors:
            value = next(iter(colors)) if len(colors) == 1 else 6
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = value
    return out
